import { system } from "../theme";

const tokenToPx = (value: string): number => {
  if (value.endsWith("px")) return parseFloat(value);
  if (value.endsWith("rem")) return parseFloat(value) * 16;
  return parseFloat(value);
};

type UseThemeReturn = {
  getToken: (token: string) => string;
  getTokenPx: (token: string) => number;
};

export const useTheme = (): UseThemeReturn => {
  const getToken = (token: string): string => system.token(token) as string;
  const getTokenPx = (token: string): number => tokenToPx(getToken(token));
  return { getToken, getTokenPx };
};
